window.__votdWeek && window.__votdWeek({"week":"2029-06-25","reading":"Doctrine and Covenants 67–70","days":[{"d":"2029-06-25","ref":"D&C 67:9","b":"D&C","c":67,"v":9,"he":"כִּי יוֹדְעִים אַתֶּם כִּי אֵין בָּהֶם עַוְלָה וַאֲשֶׁר צַדִּיק הוּא יוֹרֵד מִמַּעַל מֵאֲבִי הָאוֹרוֹת׃","en":"For ye know that there is no unrighteousness in them, and that which is righteous cometh down from above, from the Father of lights."},{"d":"2029-06-26","ref":"D&C 67:11","b":"D&C","c":67,"v":11,"he":"כִּי לֹא רָאָה אָדָם אֶת־אֱלֹהִים מֵעוֹלָם בַּבָּשָׂר בִּלְתִּי אִם כֵּן הֶחֱיָהוּ רוּחַ אֱלֹהִים׃","en":"For no man has seen God at any time in the flesh, except quickened by the Spirit of God."},{"d":"2029-06-27","ref":"D&C 68:6","b":"D&C","c":68,"v":6,"he":"לָכֵן הִתְחַזְּקוּ וְאַל תִּירְאוּ כִּי אֲנִי יְהוָה עִמָּכֶם וְאֶעֱמֹד לְצִדְּכֶם וְתָעִידוּ עָלַי גַּם יֵשׁוּעַ הַמָּשִׁיחַ כִּי אֲנִי בֶּן אֱלֹהִים חַיִּים כִּי הָיִיתִי וַאֲנִי הוֹוֶה וַאֲנִי עָתִיד לָבוֹא׃","en":"Wherefore, be of good cheer, and do not fear, for I the Lord am with you, and will stand by you; and ye shall bear record of me, even Jesus Christ, that I am the Son of the living God, that I was, that I am, and that I am to come."},{"d":"2029-06-28","ref":"D&C 68:8","b":"D&C","c":68,"v":8,"he":"לְכוּ לְכׇל־הָעוֹלָם קִרְאוּ הַבְּשׂוֹרָה לְכׇל־בְּרִיָּה בִּפׇעׇלְכֶם בַּסַּמְכוּת אֲשֶׁר נָתַתִּי לָכֶם מַטְבִּילִים בְּשֵׁם הָאָב וְהַבֵּן וְרוּחַ־הַקֹּדֶשׁ׃","en":"Go ye into all the world, preach the gospel to every creature, acting in the authority which I have given you, baptizing in the name of the Father, and of the Son, and of the Holy Ghost."},{"d":"2029-06-29","ref":"D&C 69:4","b":"D&C","c":69,"v":4,"he":"וְגַם כִּי יְקַבֵּל עֵצָה וְעֶזְרָה מֵעַבְדִּי אוֹלִיבֶר קַאוּדְרִי וַאֲחֵרִים׃","en":"And also that he receive counsel and assistance from my servant Oliver Cowdery and others."},{"d":"2029-06-30","ref":"D&C 70:8","b":"D&C","c":70,"v":8,"he":"וְהַטּוֹבוֹת יֻקְדְּשׁוּ לְיוֹשְׁבֵי צִיּוֹן וּלְדוֹרוֹתֵיהֶם כְּפִי אֲשֶׁר יִהְיוּ יוֹרְשִׁים לְפִי חֻקֵּי הַמַּלְכוּת׃","en":"And the benefits shall be consecrated unto the inhabitants of Zion, and unto their generations, inasmuch as they become heirs according to the laws of the kingdom."},{"d":"2029-07-01","ref":"D&C 70:18","b":"D&C","c":70,"v":18,"he":"הִנֵּה אֲנִי יְהוָה רַחוּם וַאֲבָרְכֵם וְיָבֹאוּ בְּשִׂמְחַת הַדְּבָרִים הָאֵלֶּה כֵּן יְהִי אָמֵן׃","en":"Behold, I, the Lord, am merciful and will bless them, and they shall enter into the joy of these things. Even so. Amen."}]});
